extern "C" TfLiteStatus ALEXA_INT8_invoke() {

#if TF_LITE_MICRO_USE_OFFLINE_OP_USER_DATA
tflite::micro::resetOfflineOpUserData( tflite::micro::ALEXA_INT8_model::precomputed_op_user_data);
#endif  // TF_LITE_MICRO_USE_OFFLINE_OP_USER_DATA

  for(size_t i = 0; i < kOpNodesCount; ++i) {
#if LOG_OP_INPUTS
    tflite::logOpInvoke(&ctx,  &tflNodes[i]);
#endif
    TfLiteStatus status = registrations[nodeData[i].used_op_index].invoke(&ctx, &tflNodes[i]);
    if (status != kTfLiteOk) {
      return status;
    }
  }
  return kTfLiteOk;
}


